import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aStr = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aStr[i]);
        }

        int half = n / 2;
        List<Integer> part1 = new ArrayList<>();
        List<Integer> part2 = new ArrayList<>();

        // Generate all subset sums for first half
        createSums1(a, 0, 0, half, m, part1);
        // Generate all subset sums for second half
        createSums2(a, half, n, 0, m, part2);

        // Remove duplicates and sort
        TreeSet<Integer> setPart1 = new TreeSet<>(part1);
        List<Integer> sortedPart1 = new ArrayList<>(setPart1);

        int bestSum = 0;

        for (int i : part2) {
            int idx = Collections.binarySearch(sortedPart1, m - i);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                int candidate = sortedPart1.get(idx - 1) + i;
                if (candidate > bestSum) {
                    bestSum = candidate;
                }
            }
        }
        System.out.println(bestSum);
    }

    private static void createSums1(int[] a, int start, int end, int half, int m, List<Integer> part1) {
        generateSums(a, start, end, 0, m, part1);
    }

    private static void createSums2(int[] a, int start, int end, int total, int m, List<Integer> part2) {
        generateSums(a, start, end, total, m, part2);
    }

    private static void generateSums(int[] a, int index, int end, int currentSum, int m, List<Integer> list) {
        if (index == end) {
            list.add(currentSum % m);
            return;
        }
        generateSums(a, index + 1, end, currentSum + a[index], m, list);
        generateSums(a, index + 1, end, currentSum, m, list);
    }
}
